      SUBROUTINE FIXREFC---- CHANGE REFERENCES TO PARAMETER WHEN ELEMENT IS MOVED TO FRONTC---- OF DATA ARRAYC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'ICOPY.CIN'      INCLUDE 'LIMITS.CIN'C-----------------------------------------------------------------------      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATAC           IEND = ISTOR(NELLIM)      DO 20 III = ICOPY, IEND      ITIE = TIE(III)      IDAT = IDATA(III)      IF (ITIE .EQ. 100 .AND. I100 .EQ. IDAT) THEN        LAKE = IANEW        DATA(III) = FAKE      ENDIF   20 CONTINUE      RETURN      END